// Quaternion helpers
function quatConjugate(q) {
    return { x: -q.x, y: -q.y, z: -q.z, w: q.w };
}

function quatMultiply(a, b) {
    return {
        w: a.w*b.w - a.x*b.x - a.y*b.y - a.z*b.z,
        x: a.w*b.x + a.x*b.w + a.y*b.z - a.z*b.y,
        y: a.w*b.y - a.x*b.z + a.y*b.w + a.z*b.x,
        z: a.w*b.z + a.x*b.y - a.y*b.x + a.z*b.w
    };
}

function rotateVector(v, q) {
    const qv = { x: v.x, y: v.y, z: v.z, w: 0 };
    const qInv = quatConjugate(q);
    const r = quatMultiply(quatMultiply(q, qv), qInv);
    return { x: r.x, y: r.y, z: r.z };
}

const A = poseA.pose;
const B = poseB.pose;

// Invert A
const qA_inv = quatConjugate(A.orientation);
const pA_inv = rotateVector({
    x: -A.position.x,
    y: -A.position.y,
    z: -A.position.z
}, qA_inv);

// Relative position
const pB_rot = rotateVector(B.position, qA_inv);
const pRel = {
    x: pB_rot.x + pA_inv.x,
    y: pB_rot.y + pA_inv.y,
    z: pB_rot.z + pA_inv.z
};

// Relative orientation
const qRel = quatMultiply(qA_inv, B.orientation);

msg.payload = {
