const threshold = 0.05;  // change limit

let prev = context.get("prev");
let curr = msg.payload;

// Get or initialize the stored list
let list = flow.get("list") || [];

if (!prev) {
    context.set("prev", curr);
    list.push(curr);
    flow.set("list", list);
    return msg;
}

// Example: check change in position[0] (customize as needed)
let changed = false;
if (prev.position && curr.position) {
    if (Math.abs(curr.position[0] - prev.position[0]) > threshold) {
        changed = true;
    }
}

// Save if flagged externally or if changed
if (flow.get("save") || changed) {
    list.push(curr);          // store entire payload
    flow.set("list", list);
    context.set("prev", curr);
    flow.set("save", false);
    return msg;
}

// Drop message if no significant change
return null;

msg.payload = {
  "name": "/robot_description_semantic"
}
return msg;

// Parse SRDF XML to extract move groups
let xmlString = msg.payload.value;

if (!xmlString) {
    msg.payload = { error: "No SRDF data received" };
    return msg;
}

// Unescape the XML string (handle \n, \t, etc.)
xmlString = xmlString.replace(/\\n/g, '\n').replace(/\\t/g, '\t').replace(/\\"/g, '"');

// Store in flow context for later use
flow.set('robot_description_semantic', xmlString);

// First, parse end effector definitions to build a map
const endEffectorMap = {}; // group_name -> parent_link
const endEffectorRegex = /<end_effector\s+name="([^"]+)"\s+parent_link="([^"]+)"\s+group="([^"]+)"\s*\/>/g;
let eeMatch;
while ((eeMatch = endEffectorRegex.exec(xmlString)) !== null) {
    const groupName = eeMatch[3];
    const parentLink = eeMatch[2];
    endEffectorMap[groupName] = parentLink;
}

// Parse XML to extract groups
const groups = [];

// Match all group definitions
const groupBlockRegex = /<group\s+name="([^"]+)">([\s\S]*?)<\/group>/g;
let match;

while ((match = groupBlockRegex.exec(xmlString)) !== null) {
    const groupName = match[1];
    const groupContent = match[2];

    // Check for subgroups (composite groups like both_arms)
    const subgroupRegex = /<group\s+name="([^"]+)"\s*\/>/g;
    const subgroups = [];
    let subMatch;
    while ((subMatch = subgroupRegex.exec(groupContent)) !== null) {
        subgroups.push(subMatch[1]);
    }

    // Check for joints (arm groups)
    const jointRegex = /<joint\s+name="([^"]+)"\s*\/>/g;
    const joints = [];
    let jointMatch;
    while ((jointMatch = jointRegex.exec(groupContent)) !== null) {
        joints.push(jointMatch[1]);
    }

    // Check for links (gripper groups)
    const linkRegex = /<link\s+name="([^"]+)"\s*\/>/g;
    const links = [];
    let linkMatch;
    while ((linkMatch = linkRegex.exec(groupContent)) !== null) {
        links.push(linkMatch[1]);
    }

    // Check for chains (if any)
    const chainRegex = /<chain\s+base_link="([^"]+)"\s+tip_link="([^"]+)"\s*\/>/g;
    const chains = [];
    let chainMatch;
    while ((chainMatch = chainRegex.exec(groupContent)) !== null) {
        chains.push({
            base: chainMatch[1],
            tip: chainMatch[2]
        });
    }

    // Determine type
    let type = 'unknown';
    if (subgroups.length > 0) {
        type = 'composite';
    } else if (joints.length > 0) {
        type = 'joints';
    } else if (chains.length > 0) {
        type = 'chain';
    } else if (links.length > 0) {
        type = 'links';
    }

    // Determine end effector count
    let endEffectorCount = 0;
    let endEffectorLinks = [];

    if (type === 'composite') {
        // For composite groups, count end effectors from subgroups
        subgroups.forEach(sg => {
            if (endEffectorMap[sg]) {
                endEffectorCount++;
                endEffectorLinks.push(endEffectorMap[sg]);
            }
        });
    } else {
        // For non-composite groups, check if this group IS an end effector
        if (endEffectorMap[groupName]) {
            endEffectorLinks.push(endEffectorMap[groupName]);
        }
        // But the group itself doesn't "have" an end effector, it IS one
        // So endEffectorCount stays 0 for grippers
        // For arms, we need to check if they have an associated end effector
        // by looking at which end effector has a parent_link in this group's chain
        endEffectorCount = endEffectorLinks.length;
    }

    groups.push({
        name: groupName,
        type: type,
        subgroups: subgroups,
        joints: joints,
        links: links,
        chains: chains,
        endEffectorCount: endEffectorCount,
        endEffectorLinks: endEffectorLinks,
        isEndEffector: endEffectorMap.hasOwnProperty(groupName)
    });
}

// Store parsed groups in flow context
global.set('move_groups', groups);

msg.payload = {
    groups: groups,
    groupNames: groups.map(g => g.name),
    count: groups.length
};

return msg;

flow.set("original_switch_msg", msg);
return {
    payload : {
        group_name: msg.payload
    }
}

