  const sr = Math.sin(rpy.roll * (Math.PI / 180) * 0.5);

  const q = {
    x: sr * cp * cy - cr * sp * sy,
    y: cr * sp * cy + sr * cp * sy,
    z: cr * cp * sy - sr * sp * cy,
    w: cr * cp * cy + sr * sp * sy
  };

  return q;
}

