function rpyToQuaternion(rpy) {

  // Convert half angles
  const cy = Math.cos(rpy.yaw * (Math.PI / 180) * 0.5);
  const sy = Math.sin(rpy.yaw * (Math.PI / 180) * 0.5);
  const cp = Math.cos(rpy.pitch * (Math.PI / 180) * 0.5);
  const sp = Math.sin(rpy.pitch * (Math.PI / 180) * 0.5);
  const cr = Math.cos(rpy.roll * (Math.PI / 180) * 0.5);
  const sr = Math.sin(rpy.roll * (Math.PI / 180) * 0.5);

  const q = {
    x: sr * cp * cy - cr * sp * sy,
    y: cr * sp * cy + sr * cp * sy,
    z: cr * cp * sy - sr * sp * cy,
    w: cr * cp * cy + sr * sp * sy
  };

  return q;
}

