// Incoming data
const name = msg.name;
const pose = msg.payload;

if (!name || !pose) {
    node.warn("Missing name or pose");
    return null;
}

// Get existing array (or init)
let poses = global.get("isaac_sim/object_poses");
if (!Array.isArray(poses)) {
    poses = [];
    node.warn("Initializing empty poses array");
}

node.warn(`[BEFORE] Array length: ${poses.length}, Adding/Updating: ${name}`);

// Get collision objects definitions
const collisionObjects = flow.get("colision_objects");

// Find existing entry
const index = poses.findIndex(p => p.name === name);

if (index === -1) {
    // New name → push
    poses.push({
        name: name,
        pose: pose
    });
    node.warn(`✓ Added new pose: ${name}`);
} else {
    // Existing name → update (optional behavior)
    poses[index].pose = pose;
    node.warn(`↻ Updated existing pose: ${name}`);
}

// Helper function to check if an object uses mesh
function isMeshObject(poseName) {
    if (!collisionObjects || !Array.isArray(collisionObjects)) {
        node.warn("No collision objects found!");
        return false;
    }

    const nameLower = poseName.toLowerCase();
    const collisionObj = collisionObjects.find(obj => 
        nameLower.includes(obj.type.toLowerCase())
    );

    if (collisionObj) {
        const hasMesh = collisionObj.mesh ? true : false;
        node.warn(`Object: ${poseName} -> Type: ${collisionObj.type} -> Has Mesh: ${hasMesh}`);
        return hasMesh;
    } else {
        node.warn(`No collision object match for: ${poseName}`);
        return false;
    }
}

// Sort: non-mesh objects first, then mesh objects, alphabetically within each group
poses.sort((a, b) => {
    const aIsMesh = isMeshObject(a.name);
    const bIsMesh = isMeshObject(b.name);

    node.warn(`Comparing: ${a.name} (mesh=${aIsMesh}) vs ${b.name} (mesh=${bIsMesh})`);

    // If types differ, non-mesh (false) comes before mesh (true)
    if (aIsMesh !== bIsMesh) {
        const result = aIsMesh ? 1 : -1;
        node.warn(`  -> Different types, result: ${result}`);
        return result;
    }

    // Same type: sort alphabetically
    return a.name.toLowerCase().localeCompare(b.name.toLowerCase());
});

// Save back to context
global.set("isaac_sim/object_poses", poses);
node.warn(`[AFTER] Saved ${poses.length} poses to global context`);
node.warn(`First 5 objects: ${poses.slice(0, 5).map(p => p.name).join(', ')}`);

// Optional outputs
msg.payload = poses;
msg.count = poses.length;

return msg;

// DEBUGGING VERSION - Add detailed logging
//node.warn("========== MARKER ENRICHMENT DEBUG START ==========");

// Check if collision objects metadata exists
const collisionObjectsMeta = flow.get("colision_objects");
//node.warn(`Collision objects metadata: ${collisionObjectsMeta ? 'FOUND' : 'NOT FOUND'}`);
if (collisionObjectsMeta) {
    //node.warn(`Metadata array length: ${collisionObjectsMeta.length}`);
    //node.warn(`Metadata types: ${collisionObjectsMeta.map(o => o.type).join(', ')}`);
}

// Check incoming message structure
//node.warn(`msg.payload exists: ${!!msg.payload}`);
//node.warn(`msg.payload type: ${typeof msg.payload}`);

if (msg.payload) {
    //node.warn(`msg.payload.markers exists: ${!!msg.payload.markers}`);
    //node.warn(`msg.payload.markers is array: ${Array.isArray(msg.payload.markers)}`);

    if (msg.payload.markers) {
        //node.warn(`Total markers received: ${msg.payload.markers.length}`);

        // Log first 3 markers in detail
        for (let i = 0; i < Math.min(3, msg.payload.markers.length); i++) {
            const marker = msg.payload.markers[i];
            //node.warn(`--- Marker ${i} ---`);
            //node.warn(`  ns: ${marker.ns}`);
            //node.warn(`  type: ${marker.type}`);
            //node.warn(`  text: ${marker.text}`);
            //node.warn(`  scale: ${JSON.stringify(marker.scale)}`);
        }
    }
}

// If we don't have valid data, stop here
if (!collisionObjectsMeta || !Array.isArray(collisionObjectsMeta)) {
    node.error("Collision objects metadata not available");
    node.status({fill: "red", shape: "ring", text: "No metadata"});
    return null;
}

if (!msg.payload || !msg.payload.markers || !Array.isArray(msg.payload.markers)) {
    //node.warn("Invalid message format - expected payload.markers array");
    node.status({fill: "red", shape: "ring", text: "Invalid format"});
    return null;
}

// Helper function to detect object type
function detectObjectType(markerNs) {
    const nsLower = markerNs.toLowerCase();
    const collisionObj = collisionObjectsMeta.find(obj => 
        nsLower.includes(obj.type.toLowerCase())
    );
    return collisionObj || null;
}

// Process markers
let enrichedCount = 0;
let meshMarkersFound = 0;
let totalMarkers = msg.payload.markers.length;

//node.warn(`Processing ${totalMarkers} markers...`);

for (const marker of msg.payload.markers) {

    // Check if this is a mesh placeholder
    if (marker.type === 1 && marker.text === "mesh") {
        meshMarkersFound++;
        //node.warn(`Found mesh marker: ${marker.ns}`);

        const objMeta = detectObjectType(marker.ns);

        if (objMeta) {
            //node.warn(`  -> Matched type: ${objMeta.type}`);
            //node.warn(`  -> Has mesh: ${!!(objMeta.mesh && objMeta.mesh.resource)}`);

            if (objMeta.mesh && objMeta.mesh.resource) {
                marker.mesh_resource = objMeta.mesh.resource;
                marker.type = 10;
                marker.scale.x = 1.0;
                marker.scale.y = 1.0;
                marker.scale.z = 1.0;
                marker.mesh_use_embedded_materials = true;

                enrichedCount++;
                //node.warn(`  -> ✓ ENRICHED with: ${marker.mesh_resource}`);
            }
        } else {
            //node.warn(`  -> ⚠ NO MATCH in metadata`);
        }
    }
}

