//node.warn(`Mesh markers enriched: ${enrichedCount}`);
//node.warn("========== DEBUG END ==========");

// Set status
if (meshMarkersFound > 0) {
    node.status({
        fill: enrichedCount > 0 ? "green" : "yellow",
        shape: enrichedCount > 0 ? "dot" : "ring",
        text: `${enrichedCount}/${meshMarkersFound} enriched`
    });
} else {
    node.status({
        fill: "blue",
        shape: "ring",
        text: `${totalMarkers} markers (no meshes)`
    });
}

