/**
 * 
 * ROS Handle Functions
 * 
 */
global.set("ROSStampToDate", function (stamp) {

    if (!stamp || stamp.secs === undefined || stamp.nsecs === undefined) {
        node.error("No valid ROS stamp found", msg);
        return null;
    }

    // Convert to milliseconds
    const ms = (stamp.secs * 1000) + Math.floor(stamp.nsecs / 1e6);

    // Create JS Date
    return new Date(ms);
});

global.set("dateToROSStamp", function (date) {

    if (!(date instanceof Date)) {
        date = new Date(date);
    }

    if (isNaN(date.getTime())) {
        node.error("Invalid Date", msg);
        return null;
    }

    // Convert
    const ms = date.getTime();

    return {
        secs: Math.floor(ms / 1000),
        nsecs: (ms % 1000) * 1e6
    }
});

// ==========================================
// GLOBAL ENUMS AND HELPERS - Initialize on Node-RED start
