// Robot Action ENUM
const RobotAction = Object.freeze({
    NONE: 0,
    MOVE_CONT_RED: 1,
    MOVE_RED_CONT: 2,
    MOVE: 10,
    GRASP: 11,
    RELEASE: 12
});

// Create reverse lookup map
const RobotActionName = Object.freeze(
    Object.fromEntries(
        Object.entries(RobotAction).map(([k, v]) => [v, k])
    )
);

// Function: Convert ENUM value to string
function actionToString(actionValue) {
    return RobotActionName[actionValue] || "UNKNOWN";
}

// Function: Convert string to ENUM value (case-insensitive)
function stringToAction(actionString) {
    if (typeof actionString !== 'string') return null;
    const normalized = actionString.toUpperCase();
    return RobotAction.hasOwnProperty(normalized) ? RobotAction[normalized] : null;
}

// Store in GLOBAL context (accessible across all flows)
global.set('RobotAction', RobotAction);
global.set('RobotActionName', RobotActionName);
global.set('actionToString', actionToString);
global.set('stringToAction', stringToAction);

// Log initialization
node.warn("✅ Global ENUMS initialized:");
node.warn("  - RobotAction: " + JSON.stringify(RobotAction));

