global.set("getNamedJointState", function (target){

    const targetName = String(target.robot_id + "_" + target.name);
    node.warn(targetName);

    // Get array from flow context
    const states = global.get("namedJointStates");

    if (!Array.isArray(states)) {
        node.error("global.namedJointStates is not an array", msg);
        return null;
    }

    // Find matching entry
    const entry = states.find(e => e.name === targetName);

    if (!entry) {
        node.warn(`JointState '${targetName}' not found`);
        return null;
    }

    if (!entry.joint_states) {
        node.error(`Entry '${targetName}' has no joint_states`, msg);
        return null;
    }

    return entry.joint_states;

});

